class Solution {
public:
    int uniqueLetterString(string s) {
        vector<int> pos[26];
        int n = s.length();
        for (int i = 0; i < 26; i++) pos[i].push_back(-1);
        for (int i = 0; i < n; i++) pos[s[i] - 'A'].push_back(i);
        for (int i = 0; i < 26; i++) pos[i].push_back(n);
        int ans = 0;
        for (int c = 0; c < 26; c++) {
            for (size_t i = 1; i + 1 < pos[c].size(); i++) {
                ans += (pos[c][i] - pos[c][i - 1]) * (pos[c][i + 1] - pos[c][i]);
            }
        }
        return ans;
    }
};

class Solution {
    public int uniqueLetterString(String s) {
        List<Integer>[] pos = new ArrayList[26];
        int n = s.length();
        for (int i = 0; i < 26; i++) {
            pos[i] = new ArrayList<>();
            pos[i].add(-1);
        }
        for (int i = 0; i < n; i++) pos[s.charAt(i) - 'A'].add(i);
        for (int i = 0; i < 26; i++) pos[i].add(n);
        int ans = 0;
        for (int c = 0; c < 26; c++) {
            for (int i = 1; i + 1 < pos[c].size(); i++) {
                ans += (pos[c].get(i) - pos[c].get(i - 1)) * (pos[c].get(i + 1) - pos[c].get(i));
            }
        }
        return ans;
    }
}

var uniqueLetterString = function(s) {
    const pos = Array.from({ length: 26 }, () => [-1]);
    const n = s.length;
    for (let i = 0; i < n; i++) {
        pos[s.charCodeAt(i) - 65].push(i);
    }
    for (let i = 0; i < 26; i++) {
        pos[i].push(n);
    }
    let ans = 0;
    for (let c = 0; c < 26; c++) {
        for (let i = 1; i + 1 < pos[c].length; i++) {
            ans += (pos[c][i] - pos[c][i - 1]) * (pos[c][i + 1] - pos[c][i]);
        }
    }
